/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { FormEvent, useContext } from 'react';

import PinAngleFill from '@pohodnik/icons/svg/RealWorld/PinAngleFill';
import X from '@pohodnik/icons/svg/Signs/X';
import clsx from 'clsx';

import PageLoader from '@components/PageLoader';
import { err, success } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';

import CommentBubble from './CommentBubble';
import styles from './styles.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';
import {
  addComment,
  addCommentsBranch,
  getComments,
  getCommentsBranch,
  pinComment,
} from '../../@services/comments.service';
import { IComment, ICommentBranch } from '../../@types/comments.types';

interface ICommentsWidgetProps {
  id_hiking?: number;
  id_position?: number;
  id_recipe?: number;
  id_route?: number;
  id_workout?: number;
  id_workout_group?: number;
  id_obstacle?: number;
  id_hiking_obstacle?: number;
  id_article?: number;
  id_hiking_article?: number;
  startText?: string;
}

const CommentsWidget: React.FC<ICommentsWidgetProps> = ({
  id_hiking = null,
  id_position = null,
  id_recipe = null,
  id_route = null,
  id_workout_group = null,
  id_workout = null,
  id_obstacle = null,
  id_hiking_obstacle = null,
  id_article = null,
  id_hiking_article = null,
  startText = 'Обсудить',
}) => {
  const [branch, setBranch] = React.useState<ICommentBranch | null>(null);
  const [comments, setComments] = React.useState<IComment[]>([]);
  const [isCommentsLoading, setIsCommentsLoading] = React.useState<boolean>(true);
  const [commentsErr, setCommentsErr] = React.useState<Error | null>(null);

  const [isCreating, setIsCreating] = React.useState<boolean>(false);
  const [isSending, setIsSending] = React.useState<boolean>(false);
  const [actualKey, setActualKey] = React.useState<string>('');

  const listRef = React.useRef<HTMLDivElement>(null);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        const br = await getCommentsBranch({
          id_hiking,
          id_position,
          id_recipe,
          id_route,
          id_workout,
          id_workout_group,
          id_obstacle,
          id_hiking_obstacle,
          id_article,
          id_hiking_article,
        });
        setBranch(br);

        br?.id && (await getComments(br.id).then(setComments));
      } catch (e) {
        setCommentsErr(e as Error);
      } finally {
        setIsCommentsLoading(false);
      }
    };

    init().catch(err);
  }, [
    id_hiking,
    id_position,
    id_recipe,
    id_route,
    id_workout,
    id_workout_group,
    id_hiking_obstacle,
    id_obstacle,
    id_article,
    id_hiking_article,
  ]);

  React.useEffect(() => {
    if (!branch) {
      return;
    }
    const getCommentsEffect = async () => {
      await getComments(branch.id).then(setComments);
      if (actualKey.length > 0) {
        success('Обновлено');
      }
    };

    getCommentsEffect().catch(err);
  }, [branch, actualKey]);

  // React.useEffect(() => {
  //     to.current = setInterval(() => setActualKey(performance.now().toString()), 30000);
  //
  //     return () => to.current && clearTimeout(to.current);
  // }, [])

  React.useEffect(() => {
    setTimeout(() => {
      listRef.current?.scrollTo({ top: Number.MAX_SAFE_INTEGER, behavior: 'smooth' });
    }, 1000);
  }, [comments]);

  const handleCreateBranch = async () => {
    try {
      setIsCreating(true);
      if (!authContext.user) return;
      const id = await addCommentsBranch({
        id_hiking,
        id_position,
        id_recipe,
        id_route,
        id_workout,
        id_workout_group,
        id_obstacle,
        id_hiking_obstacle,
        id_hiking_article,
      });
      setBranch({
        id,
        id_hiking: id_hiking ?? null,
        id_position: id_position ?? null,
        id_recipe: id_recipe ?? null,
        id_route: id_route ?? null,
        id_workout_group: id_workout_group ?? null,
        id_workout: id_workout ?? null,
        id_obstacle: id_workout ?? null,
        id_hiking_obstacle: id_workout ?? null,
        id_article: id_article ?? null,
        id_hiking_article: id_hiking_article ?? null,
        created_at: new Date(),
        user: {
          id: +authContext.user.id,
          name: authContext.user.name,
          photo: authContext.user.photo,
        },
      });
    } catch (e) {
      err(e as Error);
    } finally {
      setIsCreating(false);
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    if (!branch) {
      return;
    }

    try {
      setIsSending(true);
      const el = e.target as HTMLFormElement;

      // @ts-ignore
      const comment = el.elements.comment.value.trim();
      const id = await addComment({
        id_comments_branch: branch.id,
        id_reply_comment: null,
        comment,
        is_pinned: false,
      });

      setComments((cur) =>
        cur.concat({
          id,
          id_comments_branch: branch.id,
          id_reply_comment: null,
          comment: comment,
          is_pinned: false,
          created_at: new Date(),
          updated_at: null,
          deleted_at: null,
          user: {
            id: +authContext.user!.id,
            name: authContext.user!.name,
            photo: authContext.user!.photo,
          },
        }),
      );
      // @ts-ignore
      el.elements.comment.value = '';
      window.requestAnimationFrame(() => {
        // @ts-ignore
        el.elements.comment.focus();
      });
    } catch (e1) {
      err(e1 as Error);
    } finally {
      setIsSending(false);
    }
  };

  if (isCommentsLoading) {
    return <PageLoader />;
  }

  if (commentsErr) {
    return <PohAlert variant={AlertVariant.Danger}>{commentsErr.message}</PohAlert>;
  }

  if (!branch) {
    return (
      <div>
        <PohButton
          disabled={isCreating}
          onClick={handleCreateBranch}
          variant={ButtonVariant.Success}
        >
          {startText}
        </PohButton>
      </div>
    );
  }

  let last = 0;
  const pinnedComment = comments.find((c) => c.is_pinned);

  return (
    <section>
      {pinnedComment && (
        <div
          title="Закрепленное сообщение. Нажмите чтобы перейти"
          className={clsx('p-2', styles.pinned)}
          onClick={() =>
            document
              .getElementById(`comment-${pinnedComment.id}`)
              ?.scrollIntoView({ behavior: 'smooth' })
          }
        >
          {pinnedComment.user.id === +authContext.user!.id && (
            <PohButton
              className="float-end"
              size={ButtonSize.Small}
              icon
              onClick={async () => {
                pinComment(pinnedComment.id, !pinnedComment.is_pinned)
                  .catch(err)
                  .then((scss) => {
                    if (scss) {
                      setComments((cur) =>
                        cur.map((c) => ({
                          ...c,
                          is_pinned: !pinnedComment.is_pinned && c.id === pinnedComment.id,
                        })),
                      );
                      success(pinnedComment.is_pinned ? 'Откреплено' : 'Закреплено');
                    }
                  });
              }}
            >
              <X />
            </PohButton>
          )}
          <PinAngleFill /> {pinnedComment.comment}
        </div>
      )}
      <section ref={listRef} className={clsx(styles.messagesContainer)}>
        {comments.length > 0 &&
          comments.map((comment) => {
            const isGroup = last === comment.user.id;

            if (last !== comment.user.id) {
              last = comment.user.id;
            }

            return (
              <CommentBubble
                key={comment.id}
                comment={comment}
                isGrouped={isGroup}
                menu={[
                  comment.user.id === +authContext.user!.id && (
                    <button
                      key={`bottom-level-menu-item-111`}
                      className="dropdown-item"
                      onClick={async () => {
                        pinComment(comment.id, !comment.is_pinned)
                          .catch(err)
                          .then((scss) => {
                            if (scss) {
                              setComments((cur) =>
                                cur.map((c) => ({
                                  ...c,
                                  is_pinned: !comment.is_pinned && c.id === comment.id,
                                })),
                              );
                              success(comment.is_pinned ? 'Откреплено' : 'Закреплено');
                            }
                          });
                      }}
                      type="button"
                    >
                      Закрепить
                    </button>
                  ),
                ].filter(Boolean)}
              />
            );
          })}
      </section>
      <form onSubmit={handleSubmit} className="py-2">
        <textarea
          onKeyPress={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              (e.currentTarget.parentNode as HTMLFormElement).requestSubmit();
            }
          }}
          className="w-100 form-control"
          name="comment"
          disabled={isSending}
          placeholder={'Введите сообщение. Отправка по Enter. Перенос строки Shift+Enter'}
          required
        />
        <footer className="d-flex justify-content-between py-2">
          <PohButton
            type="button"
            disabled={isSending}
            className="h-100 flex-shrink-0"
            onClick={() => setActualKey(performance.now().toString())}
          >
            Обновить
          </PohButton>
          <PohButton
            type="submit"
            variant={ButtonVariant.Primary}
            disabled={isSending}
            className="h-100 flex-shrink-0"
          >
            Отправить
          </PohButton>
        </footer>
      </form>
    </section>
  );
};

export default CommentsWidget;
