import { IComment, ICommentBranch } from '../@types/comments.types';
import { ICommentBranchDTO, ICommentDTO } from '../@types/DTO/comments.dto.types';

export const mapCommentBranchToFront = (backData: ICommentBranchDTO): ICommentBranch => {
  return {
    id: +backData.id,

    id_hiking: backData?.id_hiking ? +backData.id_hiking : null,
    id_position: backData?.id_position ? +backData.id_position : null,
    id_recipe: backData?.id_recipe ? +backData.id_recipe : null,
    id_route: backData?.id_route ? +backData.id_route : null,
    id_article: backData?.id_article ? +backData.id_article : null,
    id_workout: backData?.id_workout ? +backData.id_workout : null,
    id_workout_group: backData?.id_workout_group ? +backData.id_workout_group : null,
    id_hiking_obstacle: backData?.id_hiking_obstacle ? +backData.id_hiking_obstacle : null,
    id_obstacle: backData?.id_obstacle ? +backData.id_obstacle : null,
    id_hiking_article: backData?.id_hiking_article ? +backData.id_hiking_article : null,

    created_at: new Date(backData.created_at),
    user: {
      id: +backData.id_author,
      name: backData.user_name,
      photo: backData.user_photo,
    },
  };
};

export const mapCommentToFront = (backData: ICommentDTO): IComment => {
  return {
    id: +backData.id,
    id_comments_branch: +backData.id_comments_branch > 0 ? +backData.id_comments_branch : null,
    id_reply_comment: +backData.id_reply_comment > 0 ? +backData.id_reply_comment : null,
    comment: backData.comment,
    is_pinned: backData.is_pinned === '1',
    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    deleted_at: backData.deleted_at ? new Date(backData.deleted_at) : null,
    user: {
      id: +backData.id_author,
      name: backData.user_name,
      photo: backData.user_photo,
    },
  };
};
