import React, { useContext } from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import PinAngleFill from '@pohodnik/icons/svg/RealWorld/PinAngleFill';
import clsx from 'clsx';

import PohAva from '@ui-kit/Ava';
import PohDropdown from '@ui-kit/Dropdown';

import styles from './styles.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';
import { IComment } from '../../@types/comments.types';

interface ICommentBubbleProp {
  comment: IComment;
  isGrouped?: boolean;
  menu?: React.ReactNode;
}

const CommentBubble: React.FC<ICommentBubbleProp> = ({ comment, isGrouped = false, menu }) => {
  const authContext = useContext(AuthContext);
  const isMy = authContext.user && +authContext.user.id === comment.user.id;

  const time =
    comment.created_at.toLocaleDateString() === new Date().toLocaleDateString()
      ? comment.created_at.toLocaleTimeString()
      : comment.created_at.toLocaleString();

  return (
    <div
      id={`comment-${comment.id}`}
      className={clsx(
        'd-flex m-2 ',
        styles.bubbleContainer,
        isMy ? 'flex-row-reverse ms-auto' : 'me-auto',
        isGrouped ? 'mt-n1' : 'my-2',
      )}
    >
      {!isGrouped ? (
        <PohAva
          src={comment.user.photo}
          style={{ top: 1 }}
          alt={comment.user.name}
          className="m-1 position-sticky"
        />
      ) : (
        <div style={{ width: 40 }} />
      )}
      <div className={clsx(isMy && 'text-end')}>
        {!isGrouped && <small className="text-muted">{comment.user.name} </small>}

        <div
          className="bg-white p-2 border position-relative"
          style={{ borderRadius: 4, maxWidth: '40vw', minWidth: '7vw' }}
        >
          {menu && (
            <PohDropdown
              className={clsx(styles.menu, isMy ? styles.leftMenu : styles.rightMenu)}
              menu={menu}
            >
              <ThreeDotsVertical />
            </PohDropdown>
          )}
          <div className={clsx(isMy && 'text-end')}>
            <small>{time}</small>
            {comment.is_pinned && <PinAngleFill className="text-warning mx-2" />}
          </div>

          <pre className="m-0" style={{ overflowWrap: 'anywhere', whiteSpace: 'pre-line' }}>
            {comment.comment}
          </pre>
        </div>
      </div>
    </div>
  );
};

export default CommentBubble;
